-- Migration 016: 11 real, local Philadelphia organizations,
-- researched individually. Pure inserts with fixed ids - safe to re-run.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('ab000000-0000-4000-8000-000000000001', null, 'Philabundance', 'The largest hunger-relief organization in the Philadelphia region, established in 1984 and running a major Hunger Relief Center in South Philadelphia.', 'https://www.philabundance.org', 'https://www.google.com/s2/favicons?domain=www.philabundance.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 14, 'United States', 'PA', 'Philadelphia', true, true, 'both', false),
  ('ab000000-0000-4000-8000-000000000002', null, 'Share Food Program', 'A Philadelphia food rescue and distribution nonprofit that recovers surplus food and redistributes it to families across the region.', 'https://www.sharefoodprogram.org', 'https://www.google.com/s2/favicons?domain=www.sharefoodprogram.org&sz=128', 'food', array['recurring'], false, false, 16, 'United States', 'PA', 'Philadelphia', true, true, 'ongoing', false),
  ('ab000000-0000-4000-8000-000000000003', null, 'ACCT Philly', 'The animal care and control provider for the City of Philadelphia, operating the city main shelter for stray and surrendered animals.', 'https://acctphilly.org', 'https://www.google.com/s2/favicons?domain=acctphilly.org&sz=128', 'animals', array['recurring'], false, false, 18, 'United States', 'PA', 'Philadelphia', true, true, 'ongoing', false),
  ('ab000000-0000-4000-8000-000000000004', null, 'Philadelphia Animal Welfare Society', 'A Philadelphia animal welfare nonprofit supporting shelter animals through adoption events, foster networks, and hands-on care volunteers.', 'https://phillypaws.org', 'https://www.google.com/s2/favicons?domain=phillypaws.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'PA', 'Philadelphia', true, true, 'ongoing', false),
  ('ab000000-0000-4000-8000-000000000005', null, 'Pennsylvania SPCA', 'One of the oldest animal welfare organizations in the country, running shelter, humane law enforcement, and adoption programs across the Philadelphia region.', 'https://www.pspca.org', 'https://www.google.com/s2/favicons?domain=www.pspca.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'PA', 'Philadelphia', true, true, 'ongoing', false),
  ('ab000000-0000-4000-8000-000000000006', null, 'YouthBuild Philadelphia Charter School', 'A Philadelphia nonprofit and charter school helping young people who left traditional high school earn their diploma while building job and leadership skills.', 'https://youthbuildphilly.org', 'https://www.google.com/s2/favicons?domain=youthbuildphilly.org&sz=128', 'community', array['leadership role'], false, false, 16, 'United States', 'PA', 'Philadelphia', true, true, 'both', false),
  ('ab000000-0000-4000-8000-000000000007', null, 'Special Olympics Pennsylvania', 'The Pennsylvania chapter of Special Olympics, providing year-round sports training and competition for athletes with intellectual disabilities statewide.', 'https://specialolympicspa.org', 'https://www.google.com/s2/favicons?domain=specialolympicspa.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 15, 'United States', 'PA', 'Philadelphia', true, true, 'both', false),
  ('ab000000-0000-4000-8000-000000000008', null, 'Philadelphia Parks and Recreation', 'The city department managing parks, trails, and recreation centers across Philadelphia, coordinating volunteer cleanup and beautification projects.', 'https://www.phila.gov', 'https://www.google.com/s2/favicons?domain=www.phila.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'PA', 'Philadelphia', true, true, 'both', false),
  ('ab000000-0000-4000-8000-000000000009', null, 'City of Philadelphia Office of Children and Families', 'The city office that connects young people and families in Philadelphia with volunteer opportunities across environment, medicine, education, and community causes.', 'https://www.phila.gov', 'https://www.google.com/s2/favicons?domain=www.phila.gov&sz=128', 'community', array['family friendly'], false, false, 0, 'United States', 'PA', 'Philadelphia', true, true, 'both', false),
  ('ab000000-0000-4000-8000-000000000010', null, 'Children''s Hospital of Philadelphia', 'One of the top pediatric hospitals in the country, running volunteer programs at both its Philadelphia and King of Prussia campuses.', 'https://volunteer.chop.edu', 'https://www.google.com/s2/favicons?domain=volunteer.chop.edu&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'PA', 'Philadelphia', true, true, 'ongoing', false),
  ('ab000000-0000-4000-8000-000000000011', null, 'Penn Medicine', 'One of the leading academic medical systems in the country, running a Student Ambassador Program for high schoolers at Pennsylvania Hospital.', 'https://www.pennmedicine.org', 'https://www.google.com/s2/favicons?domain=www.pennmedicine.org&sz=128', 'medicine', array['counts for school hours'], false, false, 14, 'United States', 'PA', 'Philadelphia', true, true, 'one-time', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('ac000000-0000-4000-8000-000000000001', 'ab000000-0000-4000-8000-000000000001', 'Volunteer at Philabundance', 'food', 'Most shifts are open to volunteers 14 and up, sorting canned goods and packing boxes during Warehouse Repack shifts, or helping prepare meals at the Philabundance Community Kitchen. A family night on the second Tuesday of each month welcomes kids as young as 8 alongside a parent.', array['good for crews', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.philabundance.org/volunteer-opportunities/', 'https://www.philabundance.org/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000002', 'ab000000-0000-4000-8000-000000000002', 'Join Philly Food Rescue', 'food', 'Volunteers use the Philly Food Rescue app to find nearby pickups, then drive, bike, or walk to collect surplus food and deliver it to recipient organizations. In 2023 alone, volunteers rescued 6.8 million pounds of food, so every trip genuinely adds up.', array['recurring'], 16, false, false, true, 'Flexible', 'https://www.sharefoodprogram.org/get-involved/philly-food-rescue-volunteer/', 'https://www.sharefoodprogram.org/get-involved/philly-food-rescue-volunteer/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000003', 'ab000000-0000-4000-8000-000000000003', 'Volunteer with ACCT Philly', 'animals', 'Volunteers commit to at least three hours a month helping with animal care, socialization, and shelter operations at the city primary animal shelter. Note this program requires volunteers to be 18 or older.', array['recurring'], 18, false, false, true, '3 hrs / month', 'https://acctphilly.org/become-a-volunteer/', 'https://acctphilly.org/become-a-volunteer/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000004', 'ab000000-0000-4000-8000-000000000004', 'Volunteer with PAWS Philadelphia', 'animals', 'Volunteers help care for dogs and cats, support the adoption process, and work events across PAWS several Philadelphia locations. It is a good option if you want variety across care, adoptions, and community outreach.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://phillypaws.org/volunteer/', 'https://phillypaws.org/volunteer/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000005', 'ab000000-0000-4000-8000-000000000005', 'Volunteer with the PSPCA', 'animals', 'Volunteers support shelter animal care, socialization, and adoption events at PSPCA facilities across the Philadelphia area. It is a well-established option if you want to be part of a long-running local animal welfare organization.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.pspca.org/volunteer', 'https://www.pspca.org/volunteer', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000006', 'ab000000-0000-4000-8000-000000000006', 'Volunteer with YouthBuild Philly', 'community', 'Volunteers support students through tutoring, mentoring, and hands-on project support as they work toward their diploma and career goals. It is a meaningful option if you want your service to directly support other young people getting back on track academically.', array['leadership role'], 16, false, false, true, 'Varies', 'https://youthbuildphilly.org/volunteer/', 'https://youthbuildphilly.org/volunteer/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000007', 'ab000000-0000-4000-8000-000000000007', 'Volunteer with Special Olympics Pennsylvania', 'sports', 'Volunteers can coach, assistant coach, help manage events, or simply cheer on athletes at competitions across the state. It is a flexible option whether you want a big commitment as a coach or a lighter one supporting event days.', array['recurring', 'leadership role'], 15, false, false, true, '1-2 hrs / week', 'https://specialolympicspa.org/volunteer-opportunities', 'https://specialolympicspa.org/volunteer-opportunities', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000008', 'ab000000-0000-4000-8000-000000000008', 'Volunteer with Philadelphia Parks and Recreation', 'environment', 'Volunteers take part in park cleanup and beautification days, resource management projects, and Park Friends group activities across the city. It is an easy way to find an outdoor project close to home in any Philadelphia neighborhood.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.phila.gov/departments/philadelphia-parks-recreation/get-involved/business-and-individual-volunteer-opportunities/', 'https://www.phila.gov/departments/philadelphia-parks-recreation/get-involved/business-and-individual-volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000009', 'ab000000-0000-4000-8000-000000000009', 'Ready, Set, Volunteer with the City of Philadelphia', 'community', 'This city resource curates volunteer opportunities across many causes specifically for middle and high school students, making it a great starting point if you are not sure yet where to focus. Opportunities span mentoring, environment, sports, and community-building.', array['family friendly'], 0, false, false, true, 'Varies', 'https://www.phila.gov/2022-08-15-ready-set-volunteer/', 'https://www.phila.gov/2022-08-15-ready-set-volunteer/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000010', 'ab000000-0000-4000-8000-000000000010', 'Volunteer at CHOP', 'medicine', 'Volunteers support patients, families, and hospital operations across CHOP two campuses, with roles ranging from patient-facing support to administrative help. It is a strong option if you are seriously considering pediatric medicine as a career.', array['counts for school hours'], 15, false, false, true, 'Varies', 'https://volunteer.chop.edu/', 'https://volunteer.chop.edu/', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA'),
  ('ac000000-0000-4000-8000-000000000011', 'ab000000-0000-4000-8000-000000000011', 'Join the Penn Medicine Student Ambassador Program', 'medicine', 'Students 14 to 17 get a behind-the-scenes look at healthcare careers through the Student Ambassador Program at Pennsylvania Hospital, open to anyone curious about medicine, not just students already set on a healthcare path. It is a great low-pressure way to explore the field.', array['counts for school hours'], 14, false, false, true, 'Varies', 'https://www.pennmedicine.org/volunteering/pennsylvania-hospital', 'https://www.pennmedicine.org/volunteering/pennsylvania-hospital', '2026-01-01T00:00:00Z', 'Philadelphia', 'PA')
on conflict (id) do nothing;
